		_ = util.WriteFile(fs, name, []byte("x"), 0o644)
		_ = util.WriteFile(fs, "z", []byte("x"), 0o644)
		st, err := w.Status()
		fmt.Printf("Status with %q: err=%v st=%v\n", name, err, st)
